data.curl:
curl --location --request POST 'https://www.runninghub.cn/task/openapi/ai-app/run' \
--header 'Host: www.runninghub.cn' \
--header 'Content-Type: application/json' \
--data-raw '{
    "webappId": "null",
    "apiKey": "<RUNNINGHUB_API_KEY>",
    "nodeInfoList": [
        {
            "nodeId": "257",
            "fieldName": "image",
            "fieldValue": "fc1c483ef460f315a334d378580c78f8e753b70a6ae05495be3205b9652e8eff.jpg",
            "description": "上传平面白图"
        },
        {
            "nodeId": "253",
            "fieldName": "text",
            "fieldValue": "Convert the 2D floor plan into a detailed 3D view with realistic lighting effects and natural shadows, including soft ambient light from ceiling lights, directional light from window sources, and warm spotlight from table lamps, while preserving the exact room layout, architectural elements, spatial arrangement, and furniture positions. Add accurate material reflectivity to surfaces such as glass, metal, and polished wood to enhance the photorealistic quality and visual depth of the scene.\n",
            "description": "提示词（可不修改，只能输入英文）"
        },
        {
            "nodeId": "260",
            "fieldName": "width",
            "fieldValue": "1600",
            "description": "出图尺寸01（01和02要一致）"
        },
        {
            "nodeId": "260",
            "fieldName": "height",
            "fieldValue": "1600",
            "description": "出图尺寸02（01和02要一致）"
        }
    ]
}'
